# idea: champion-inspired 5-scale aniso Gabor with rich per-scale stats and dual path
"""
Re-implementation of champion-class architecture: 5-scale anisotropic Gabors on
standardized opponent, raw spatial maps, per-scale orientation stats, per-orientation
color-form products, cross-scale products, HMAX templates, CNN hierarchy.
"""
import math
import torch
import torch.nn.functional as F

SEED = 42
NO = 8  # orientations
MAP_POW = 0.015
FORM_POW = 0.30
SCALES = [
    # (res, ksize, wavelength, energy_grid, form_grid)
    (128, 7, 1.5, 6, 2),    # vfine
    (128, 7, 4.0, 8, 3),    # fine
    (64,  9, 6.5, 6, 3),    # mid
    (32,  9, 8.0, 4, 2),    # coarse
    (16,  7, 6.0, 3, 1),    # broad
]
N_TEMPLATES = 96
TMPL_SZ = 5
N_C1 = 3 * NO


class Model:
    name = "gram-texture-v1"
    idea = "Champion-inspired narrow Gabor + MAP=0.015 + sigma=0.18 + pow(0.6) Gram gain=3"
    description = (
        "Combines champion innovations with orientation Gram texture. Narrower Gabor "
        "(sx=0.26k, sy=0.48k) matches V1 elongated tuning. MAP=0.015 for graded presence, "
        "FORM=0.30 stronger compression. Foveation sigma=0.18. Gain=5 on thresholds. "
        "Plus pow(0.6) orientation Gram (gain=3) for IT texture co-occurrence."
    )
    insight = (
        "Global champion at 0.7119 uses narrower Gabors, lower MAP compression, and "
        "pre-collected coarse features. Adopting those parameters with my Gram texture "
        "features may push further. Key: narrower Gabor sx=0.26 better matches elongated "
        "V1 simple cell tuning curves."
    )
    n_params = 0  # computed in _build

    def __init__(self):
        self._banks = {}
        self._s2 = None
        self._line_bank_cache = {}
        self._n_params = None

    @property
    def n_params(self):
        if self._n_params is None:
            self._compute_params()
        return self._n_params

    def _compute_params(self):
        total = 0
        for _, k, _, _, _ in SCALES:
            total += 2 * NO * k * k  # Gabor kernels
        total += NO * 5 * 5  # line kernels
        total += N_TEMPLATES * N_C1 * TMPL_SZ * TMPL_SZ  # HMAX templates
        total += 48 * N_C1 * 5 * 5 + 48 * 48 * 5 * 5  # CNN
        self._n_params = total

    def _gabor_bank(self, device, dtype, ksize, wavelength):
        key = (device.type, device.index, str(dtype), ksize, float(wavelength))
        if key in self._banks:
            return self._banks[key]
        r = (ksize - 1) / 2.0
        coords = torch.linspace(-r, r, ksize, device=device, dtype=dtype)
        yy, xx = torch.meshgrid(coords, coords, indexing='ij')
        filts = []
        sx = 0.26 * ksize
        sy = 0.48 * ksize
        for i in range(NO):
            theta = math.pi * i / NO
            ct, st = math.cos(theta), math.sin(theta)
            xr = xx * ct + yy * st
            yr = -xx * st + yy * ct
            env = torch.exp(-(xr**2 / (2*sx*sx) + yr**2 / (2*sy*sy)))
            for phase in (0.0, math.pi/2):
                f = env * torch.cos(2*math.pi*xr/wavelength + phase)
                f = f - f.mean()
                f = f / (f.square().sum().sqrt().clamp_min(1e-6))
                filts.append(f)
        bank = torch.stack(filts, 0).unsqueeze(1)
        self._banks[key] = bank
        return bank

    def _line_bank(self, device, dtype):
        key = (device.type, device.index, str(dtype))
        if key in self._line_bank_cache:
            return self._line_bank_cache[key]
        k = 5
        r = 2.0
        coords = torch.linspace(-r, r, k, device=device, dtype=dtype)
        yy, xx = torch.meshgrid(coords, coords, indexing='ij')
        kernels = []
        for i in range(NO):
            theta = math.pi * i / NO
            par = xx*math.cos(theta) + yy*math.sin(theta)
            ort = -xx*math.sin(theta) + yy*math.cos(theta)
            lk = torch.exp(-(par**2/8 + ort**2/0.5))
            lk[k//2, k//2] = 0.0
            lk = lk / lk.sum().clamp_min(1e-6)
            kernels.append(lk)
        bank = torch.stack(kernels, 0).unsqueeze(1)
        self._line_bank_cache[key] = bank
        return bank

    def _build_s2(self, device, dtype):
        if self._s2 is not None:
            return
        g = torch.Generator().manual_seed(SEED)
        t = torch.randn(N_TEMPLATES, N_C1, TMPL_SZ, TMPL_SZ, generator=g)
        t = t - t.mean(dim=(1,2,3), keepdim=True)
        norms = t.reshape(N_TEMPLATES, -1).norm(dim=1, keepdim=True).reshape(N_TEMPLATES, 1, 1, 1)
        self._s2 = (t / (norms + 1e-8)).to(device=device, dtype=dtype)
        g2 = torch.Generator().manual_seed(SEED + 1)
        self._cnn_w1 = (torch.randn(48, N_C1, 5, 5, generator=g2) * math.sqrt(2.0/(N_C1*25))).to(device=device, dtype=dtype)
        self._cnn_w2 = (torch.randn(48, 48, 5, 5, generator=g2) * math.sqrt(2.0/(48*25))).to(device=device, dtype=dtype)

    @staticmethod
    def _center_weight(H, W, sigma_frac, device, dtype):
        cy, cx = (H-1)/2, (W-1)/2
        sy, sx = H * sigma_frac, W * sigma_frac
        y = torch.arange(H, device=device, dtype=dtype) - cy
        x = torch.arange(W, device=device, dtype=dtype) - cx
        yy, xx = torch.meshgrid(y, x, indexing='ij')
        g = torch.exp(-(yy**2 / (2*sy*sy) + xx**2 / (2*sx*sx)))
        g = g / g.mean()  # normalize so mean weight = 1 (preserves scale)
        return g.unsqueeze(0).unsqueeze(0)

    @staticmethod
    def _pool(t, g):
        return F.adaptive_avg_pool2d(t, g).flatten(1)

    @staticmethod
    def _resize(t, sz):
        if t.shape[-1] == sz:
            return t
        return F.interpolate(t, (sz, sz), mode='area')

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X).float()
        n = X.shape[0]
        flat = X.reshape(n, -1)
        side = round(math.sqrt(flat.shape[1] / 3))
        x = flat.reshape(n, side, side, 3).permute(0, 3, 1, 2).contiguous()
        device, dtype = x.device, x.dtype
        self._build_s2(device, dtype)

        # Opponent channels
        r, g_c, b = x[:,0:1], x[:,1:2], x[:,2:3]
        lum = 0.299*r + 0.587*g_c + 0.114*b
        rg = (r - g_c) / math.sqrt(2)
        by = (0.5*(r+g_c) - b) * math.sqrt(2/3)
        opp = torch.cat([lum, rg, by], 1)

        # Standardize for Gabor
        mu = opp.mean(dim=(2,3), keepdim=True)
        std = (opp - mu).square().mean(dim=(2,3), keepdim=True).sqrt().clamp_min(0.05)
        norm_opp = (opp - mu) / std

        results = []
        cs = 32
        for si in range(0, n, cs):
            ei = min(si + cs, n)
            batch_opp = opp[si:ei]
            batch_norm = norm_opp[si:ei]
            batch_x = x[si:ei]
            B = batch_opp.shape[0]
            feats = []

            # Raw spatial + energy
            feats.append(self._resize(batch_opp, 18).flatten(1))
            feats.append(self._pool(batch_opp.square(), 14))
            feats.append(self._pool(batch_opp.abs().clamp_max(4), 4))

            # Color moments
            flat_ch = batch_opp.flatten(2)
            ch_mean = flat_ch.mean(dim=2)
            ch_std = flat_ch.std(dim=2).clamp_min(1e-4)
            z = (flat_ch - ch_mean.unsqueeze(2)) / ch_std.unsqueeze(2)
            ch_skew = z.pow(3).mean(dim=2).clamp(-8, 8)
            ch_kurt = z.pow(4).mean(dim=2).clamp(0, 16)
            feats.append(torch.cat([ch_mean, ch_std, ch_skew, ch_kurt], 1))  # 12

            # Threshold histograms
            thresholds = torch.tensor([[0.15,0.30,0.45,0.60,0.75],
                                       [-0.35,-0.20,0.00,0.20,0.35],
                                       [-0.35,-0.20,0.00,0.20,0.35]], device=device, dtype=dtype)
            cumul = (flat_ch.unsqueeze(2) > thresholds.view(1,3,5,1)).float().mean(dim=3)
            feats.append(cumul.flatten(1) * 5.0)  # gain on thresholds

            # Local second moments (variance in 4x4 grid cells)
            local_mean = F.adaptive_avg_pool2d(batch_opp, 4)
            local_sq = F.adaptive_avg_pool2d(batch_opp.square(), 4)
            local_var = (local_sq - local_mean.square()).clamp_min(0)
            feats.append(local_var.flatten(1))  # 48
            # Coarser variance
            lm6 = F.adaptive_avg_pool2d(batch_opp, 6)
            ls6 = F.adaptive_avg_pool2d(batch_opp.square(), 6)
            feats.append((ls6 - lm6.square()).clamp_min(0).flatten(1))  # 108

            # Local Binary Pattern histogram (micro-texture for IT)
            lum_small = self._resize(batch_opp[:, 0:1], 64)  # 64x64 luminance
            # Compare center pixel with 4 neighbors (simplified LBP)
            pad_lum = F.pad(lum_small, (1, 1, 1, 1), mode='reflect')
            center = lum_small
            # 4 directional comparisons -> 16 patterns
            bits = []
            for dy, dx in [(-1,0), (1,0), (0,-1), (0,1)]:
                neighbor = pad_lum[:, :, 1+dy:1+dy+64, 1+dx:1+dx+64]
                bits.append((center > neighbor).float())
            # Encode as 4-bit pattern (0-15)
            pattern = bits[0]*8 + bits[1]*4 + bits[2]*2 + bits[3]
            # Histogram: count each pattern (16 bins)
            lbp_hist = torch.zeros(B, 16, device=device, dtype=dtype)
            for p in range(16):
                lbp_hist[:, p] = (pattern == p).float().sum(dim=(1, 2, 3))
            lbp_hist = lbp_hist / (64*64)  # normalize
            feats.append(lbp_hist * 5.0)  # 16 dims, gain=5

            # FFT spectral features (compact: 16 dims)
            lum_fft = batch_opp[:, 0]  # (B, H, W)
            fft2d = torch.fft.fft2(lum_fft)
            power = torch.fft.fftshift(torch.abs(fft2d)**2, dim=(-2, -1))
            log_pow = torch.log(power + 1e-8)
            H, W = lum_fft.shape[-2], lum_fft.shape[-1]
            cy, cx = H//2, W//2
            y_c = torch.arange(H, device=device).float() - cy
            x_c = torch.arange(W, device=device).float() - cx
            yy, xx = torch.meshgrid(y_c, x_c, indexing='ij')
            dist = torch.sqrt(yy**2 + xx**2)
            angle = torch.atan2(yy, xx)
            max_d = float(min(cy, cx))
            # 8 radial bins
            rbins = torch.linspace(0, max_d, 9, device=device)
            fft_feats = []
            for i in range(8):
                m = ((dist >= rbins[i]) & (dist < rbins[i+1])).float()
                cnt = m.sum() + 1e-8
                fft_feats.append((log_pow * m.unsqueeze(0)).sum(dim=(1,2)) / cnt)
            # 8 angular bins
            abins = torch.linspace(-math.pi, math.pi, 9, device=device)
            for i in range(8):
                m = ((angle >= abins[i]) & (angle < abins[i+1]) & (dist < max_d)).float()
                cnt = m.sum() + 1e-8
                fft_feats.append((log_pow * m.unsqueeze(0)).sum(dim=(1,2)) / cnt)
            feats.append(torch.stack(fft_feats, dim=1))  # (B, 16)
            # Color-channel FFT (compact: 12 dims each)
            for ci in [1, 2]:
                ch_fft = batch_opp[:, ci]
                fft_c = torch.fft.fft2(ch_fft)
                pow_c = torch.fft.fftshift(torch.abs(fft_c)**2, dim=(-2,-1))
                lp_c = torch.log(pow_c + 1e-8)
                cf = []
                for i in range(6):
                    m = ((dist >= rbins[i]) & (dist < rbins[i+1])).float()
                    cnt = m.sum() + 1e-8
                    cf.append((lp_c * m.unsqueeze(0)).sum(dim=(1,2)) / cnt)
                for i in range(6):
                    m = ((angle >= abins[i]) & (angle < abins[i+1]) & (dist < max_d)).float()
                    cnt = m.sum() + 1e-8
                    cf.append((lp_c * m.unsqueeze(0)).sum(dim=(1,2)) / cnt)
                feats.append(torch.stack(cf, dim=1))

            # Gradient magnitude
            dx = F.pad(batch_opp[:,0:1,:,1:] - batch_opp[:,0:1,:,:-1], (0,1,0,0))
            dy = F.pad(batch_opp[:,0:1,1:,:] - batch_opp[:,0:1,:-1,:], (0,0,0,1))
            grad_mag = (dx**2 + dy**2 + 1e-4).sqrt().clamp_max(6) * 5.0  # gain=5
            feats.append(self._pool(grad_mag, 8))  # 64
            grad_angle = torch.atan2(dy, dx + 1e-8)
            for bi in range(4):
                ac = bi * math.pi/4 - math.pi/2
                w = torch.cos(grad_angle - ac).clamp_min(0)
                feats.append(self._pool(grad_mag * w, 4))  # 16 each = 64

            # Center-surround
            lum_coarse = F.avg_pool2d(batch_opp[:,0:1], 8, stride=1, padding=4)
            lum_coarse = lum_coarse[:,:,:batch_opp.shape[2],:batch_opp.shape[3]]
            cs_c = (batch_opp[:,0:1] - lum_coarse).abs().clamp_max(4) * 5.0  # CS gain=5
            feats.append(self._pool(cs_c, 6))  # 36

            # Color gradient magnitude (rg and by channels)
            for ci_g in [1, 2]:
                dxc = F.pad(batch_opp[:,ci_g:ci_g+1,:,1:] - batch_opp[:,ci_g:ci_g+1,:,:-1], (0,1,0,0))
                dyc = F.pad(batch_opp[:,ci_g:ci_g+1,1:,:] - batch_opp[:,ci_g:ci_g+1,:-1,:], (0,0,0,1))
                gmc = (dxc**2 + dyc**2 + 1e-4).sqrt().clamp_max(4) * 5.0
                feats.append(self._pool(gmc, 4))  # 16 each

            # Color center-surround
            for ci_cs in [1, 2]:
                ch_coarse = F.avg_pool2d(batch_opp[:,ci_cs:ci_cs+1], 8, stride=1, padding=4)
                ch_coarse = ch_coarse[:,:,:batch_opp.shape[2],:batch_opp.shape[3]]
                cs_ch = (batch_opp[:,ci_cs:ci_cs+1] - ch_coarse).abs().clamp_max(4) * 5.0
                feats.append(self._pool(cs_ch, 4))  # 16 each

            # Global luminance-color covariance
            flat_lc = batch_opp.flatten(2)  # (B, 3, HW)
            cov_lr = (flat_lc[:,0] * flat_lc[:,1]).mean(dim=1, keepdim=True)
            cov_lb = (flat_lc[:,0] * flat_lc[:,2]).mean(dim=1, keepdim=True)
            cov_rb = (flat_lc[:,1] * flat_lc[:,2]).mean(dim=1, keepdim=True)
            feats.append(torch.cat([cov_lr, cov_lb, cov_rb], dim=1))  # 3

            # Spatial frequency slope (1/f statistic per channel)
            for ci_sf in range(3):
                ch_sf = batch_opp[:, ci_sf]
                fft_sf = torch.fft.fft2(ch_sf)
                pow_sf = torch.fft.fftshift(torch.abs(fft_sf)**2, dim=(-2,-1))
                # Radial average in log-log space
                H_sf, W_sf = ch_sf.shape[-2], ch_sf.shape[-1]
                cy_sf, cx_sf = H_sf//2, W_sf//2
                y_sf = torch.arange(H_sf, device=device).float() - cy_sf
                x_sf = torch.arange(W_sf, device=device).float() - cx_sf
                yy_sf, xx_sf = torch.meshgrid(y_sf, x_sf, indexing='ij')
                dist_sf = torch.sqrt(yy_sf**2 + xx_sf**2)
                # Total power in low/mid/high frequency bands
                low = (dist_sf < H_sf/8).float()
                mid = ((dist_sf >= H_sf/8) & (dist_sf < H_sf/4)).float()
                high = ((dist_sf >= H_sf/4) & (dist_sf < H_sf/2)).float()
                for mask in [low, mid, high]:
                    cnt = mask.sum() + 1e-8
                    feats.append((torch.log(pow_sf + 1e-8) * mask.unsqueeze(0)).sum(dim=(1,2), keepdim=True).reshape(B, 1) / cnt)

            # Multi-grid color
            color_all = torch.cat([batch_x, batch_opp], 1)
            for grid in (8, 4, 2):
                feats.append(self._pool(color_all, grid))

            # Opponent Gram matrix (color co-occurrence)
            opp_flat = batch_opp.flatten(2)  # (B, 3, HW)
            opp_gram = torch.bmm(opp_flat, opp_flat.transpose(1,2))  # (B, 3, 3)
            opp_gram = opp_gram / (opp_flat.shape[2] + 1e-6)
            idx3 = torch.triu_indices(3, 3)
            feats.append(opp_gram[:, idx3[0], idx3[1]].clamp_max(10))  # 6 dims

            # 5-scale Gabor
            prev_form_e = None
            for res, ksize, wl, eg, fg in SCALES:
                src = self._resize(batch_norm, min(res, side))
                bank = self._gabor_bank(device, dtype, ksize, wl)
                y = F.conv2d(src.reshape(B*3, 1, src.shape[-2], src.shape[-1]),
                             bank, padding=ksize//2)
                y = y.reshape(B, 3, NO, 2, y.shape[-2], y.shape[-1])
                energy = (y[:,:,:,0]**2 + y[:,:,:,1]**2 + 1e-6).sqrt()

                map_e = energy.clamp_min(1e-6).pow(MAP_POW)
                form_e = energy.clamp_min(1e-6).pow(FORM_POW)

                flat_map = map_e.reshape(B, N_C1, y.shape[-2], y.shape[-1])
                flat_form = form_e.reshape(B, N_C1, y.shape[-2], y.shape[-1])

                # Foveated form energy for mid-level features
                lum_form = form_e[:, 0]  # (B, NO, H, W)
                _, _, fH, fW = lum_form.shape
                cw = self._center_weight(fH, fW, 0.18, device, dtype)
                fov_form_e = form_e * cw  # all 3 channels foveated

                contrast = lum_form.mean(dim=1, keepdim=True)
                orient_var = lum_form.var(dim=1, keepdim=True)
                peak = lum_form.amax(dim=1, keepdim=True)
                selectivity = (peak / (contrast + 0.01)).clamp_max(8)
                divnorm = lum_form / (contrast + 0.1)

                feats.append(self._pool(contrast * cw, eg))
                feats.append(self._pool(orient_var.sqrt().clamp_max(4) * cw, eg))
                feats.append(self._pool(peak * cw, eg))
                feats.append(self._pool(selectivity * cw, eg))
                feats.append(self._pool(divnorm.reshape(B, NO, *divnorm.shape[-2:]) * cw, max(eg//2, 2)))

                # Retinotopic maps
                feats.append(self._pool(flat_map, eg))
                # Global presence
                feats.append(flat_form.flatten(2).amax(dim=2))
                feats.append(flat_form.flatten(2).square().mean(dim=2).sqrt())

                # Texture RMS and peak
                tex_rms = form_e.square().mean(dim=2).sqrt()
                tex_peak = form_e.amax(dim=2)
                feats.append(self._pool(tex_rms, max(eg-1, 2)))
                feats.append(self._pool(tex_peak, fg))

                # Junctions on foveated luminance
                fov_lum = fov_form_e[:, 0]
                pooled_j = F.avg_pool2d(fov_lum, 3, stride=1, padding=1)
                bent = 0.5*(torch.roll(pooled_j, 2, dims=1) + torch.roll(pooled_j, -2, dims=1))
                orth = torch.roll(pooled_j, NO//2, dims=1)
                bends = (fov_lum * bent).clamp_min(0).sqrt()
                corners = (fov_lum * orth).clamp_min(0).sqrt()
                junc = torch.cat([bends, corners], 1).clamp_max(8).sqrt()
                feats.append(self._pool(junc, eg))
                feats.append(junc.flatten(2).amax(dim=2))

                # End-stop on foveated
                line_b = self._line_bank(device, dtype)
                support = F.conv2d(fov_lum, line_b, padding=2, groups=NO)
                es = F.relu(fov_lum - 0.8*support)
                es_s = es.square().mean(dim=1, keepdim=True).sqrt().clamp_max(8).sqrt()
                feats.append(self._pool(es_s, fg))

                # Orientation summary on foveated (mean and peak per channel)
                for ci_s in range(3):
                    ch_fe = fov_form_e[:, ci_s]  # (B, NO, H, W)
                    ch_mean = ch_fe.mean(dim=1, keepdim=True)
                    ch_peak = ch_fe.amax(dim=1, keepdim=True)
                    feats.append(self._pool(ch_mean, max(eg-1, 2)))
                    feats.append(self._pool(ch_peak, max(eg-1, 2)))

                # Color-form products on foveated
                lum_e = fov_form_e[:, 0]
                rg_e = fov_form_e[:, 1]
                by_e = fov_form_e[:, 2]
                lr = (lum_e * rg_e + 1e-4).sqrt()
                lb = (lum_e * by_e + 1e-4).sqrt()
                feats.append(self._pool(lr.reshape(B, NO, *lr.shape[-2:]), fg))
                feats.append(self._pool(lb.reshape(B, NO, *lb.shape[-2:]), fg))
                # Cross-chromatic rg×by
                rb = (rg_e * by_e + 1e-4).sqrt()
                feats.append(self._pool(rb.reshape(B, NO, *rb.shape[-2:]), max(fg-1, 1)))

                # Orientation Gram on sqrt-compressed energy (texture co-occurrence)
                sqrt_energy = energy[:, 0].clamp_min(1e-6).pow(0.6).reshape(B, NO, -1)  # sqrt for moderate compression
                gram = torch.bmm(sqrt_energy, sqrt_energy.transpose(1,2))
                hw = sqrt_energy.shape[2]
                gram = gram / (hw + 1e-6)
                idx = torch.triu_indices(NO, NO)
                gram_feats = gram[:, idx[0], idx[1]]  # (B, 36)
                feats.append(gram_feats.clamp_max(20) * 3.0)

                # Orientation summary on foveated
                fov_lum2 = fov_form_e[:, 0]
                mean_e = fov_lum2.mean(dim=1, keepdim=True)
                peak_e = fov_lum2.amax(dim=1, keepdim=True)
                feats.append(self._pool(mean_e, eg))
                feats.append(self._pool(peak_e, eg))

                # HMAX at fine+mid
                if res >= 64:
                    pk = 4 if res == 128 else 2
                    c1 = F.max_pool2d(flat_form, pk, pk)
                    s2 = F.conv2d(c1, self._s2, padding=TMPL_SZ//2)
                    feats.append(F.relu(s2).flatten(2).amax(dim=2))
                    if res == 128:
                        h1 = F.relu(F.conv2d(c1, self._cnn_w1, padding=2))
                        h1 = F.max_pool2d(h1, 2, 2)
                        h2 = F.relu(F.conv2d(h1, self._cnn_w2, padding=2))
                        feats.append(F.adaptive_max_pool2d(h2, 1).reshape(B, -1))
                        feats.append(F.adaptive_avg_pool2d(h2, 3).reshape(B, -1))

                # Cross-scale products
                if prev_form_e is not None:
                    csg = 3
                    prev_p = F.adaptive_avg_pool2d(prev_form_e[:, 0], csg)
                    curr_p = F.adaptive_avg_pool2d(form_e[:, 0], csg)
                    cross = (prev_p * curr_p + 1e-4).sqrt()
                    feats.append(cross.reshape(B, -1))

                prev_form_e = form_e

            all_f = torch.cat(feats, 1)
            all_f = torch.nan_to_num(all_f, nan=0.0, posinf=0.0, neginf=0.0)
            if all_f.shape[1] > 9999:
                all_f = all_f[:, :9999]
            results.append(all_f)

        return torch.cat(results, 0)


MODEL = Model()
